import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Testing the JavaScript calculator","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/TESTING.html"}],["meta",{"property":"og:title","content":"Testing the JavaScript calculator | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/TESTING.html"}],["meta",{"name":"twitter:title","content":"Testing the JavaScript calculator | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"TESTING.md","filePath":"TESTING.md","lastUpdated":1793879193000}`),a={name:`TESTING.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="testing-the-javascript-calculator" tabindex="-1">Testing the JavaScript calculator <a class="header-anchor" href="#testing-the-javascript-calculator" aria-label="Permalink to “Testing the JavaScript calculator”">​</a></h1><p>Use Node.js 22 or newer from the repository root.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The test command runs the JavaScript suite with Node&#39;s built-in test runner. The same suite is executed by GitHub Actions. The repository also exposes <code>npm run test:unit</code> for the test files under <code>tests/js</code>.</p><h2 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to “Coverage”">​</a></h2><p>The suite includes:</p><ul><li>Financial models, dates, leap-year calculations, FD eligibility, AIT and transfer fees.</li><li>Inflow/outflow schedules, periodic payouts, maturities and all supported outflow policies.</li><li>Immutable normalized simulation contexts and revision-bound strategy contracts.</li><li>Transactional booking, transfer and same-date batch execution, including rollback when a later operation is invalid.</li><li>Greedy, GAML, Absolute and GSS strategy behaviour.</li><li>Frozen pre-refactor execution oracles that compare normalized booking and event ledgers for Greedy, GAML, Absolute and GSS.</li><li>Search diagnostics, GSS recursive goal contraction, ancestor reforecasting and finalization lifecycle.</li><li>Architecture checks that strategies expose planning sessions rather than <code>simulate()</code> execution adapters, and that CLI/browser entry points use <code>SimulationEngine</code>.</li></ul><h2 id="production-execution-path" tabindex="-1">Production execution path <a class="header-anchor" href="#production-execution-path" aria-label="Permalink to “Production execution path”">​</a></h2><p>The CLI and browser application both use the shared JavaScript engine. Production calculations enter through <code>SimulationEngine.run()</code>; the engine drives strategy sessions, <code>SimulationRuntime</code> owns actual chronological execution, and the engine performs finalization exactly once.</p><h2 id="what-passing-tests-do-not-prove" tabindex="-1">What passing tests do not prove <a class="header-anchor" href="#what-passing-tests-do-not-prove" aria-label="Permalink to “What passing tests do not prove”">​</a></h2><p>A green test suite proves the covered contracts and regression scenarios, not every possible financial input or parity with every historical Python result. The frozen JavaScript oracles protect the pre-refactor strategy ledgers; they are not a guarantee that live bank products, rates or external assumptions are current. Add focused deterministic fixtures when changing financial semantics or strategy decision rules.</p>`,11)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};